CustomField.formula:
IF(
    /* Step 1: Check if the Win Date is empty. If it is, return null */
    ISBLANK(Most_Recent_Win_Date__c), 
    NULL, 

    /* Step 2: Calculate the difference in years and convert that into months */
    (YEAR(TODAY()) - YEAR(Most_Recent_Win_Date__c)) * 12 
    + 
    /* Step 3: Add or subtract the difference between the calendar months */
    (MONTH(TODAY()) - MONTH(Most_Recent_Win_Date__c))
)
